                                "solutionCode": "import java.util.Scanner;\npublic class Main {\n    public static void main(String[] args) {\n        int n = new Scanner(System.in).nextInt();\n        int[][] m = new int[n][n];\n        int val=1, t=0, b=n-1, l=0, r=n-1;\n        while(val<=n*n) {\n            for(int i=l; i<=r; i++) m[t][i]=val++; t++;\n            for(int i=t; i<=b; i++) m[i][r]=val++; r--;\n            if(t<=b) { for(int i=r; i>=l; i--) m[b][i]=val++; b--; }\n            if(l<=r) { for(int i=b; i>=t; i--) m[i][l]=val++; l++; }\n        }\n        for(int[] row:m) { for(int x:row) System.out.printf(\"%3d \", x); System.out.println(); }\n    }\n}"
